    assertFalse(new MessageSearches().isMatch(SearchQuery.uid(range(1728, 1728)), row, recent, log));
    assertTrue(new MessageSearches().isMatch(SearchQuery.uid(range(1729, 1729)), row, recent, log));
    assertFalse(new MessageSearches().isMatch(SearchQuery.uid(range(1730, 1730)), row, recent, log));
    assertFalse(new MessageSearches().isMatch(SearchQuery.uid(range(1, 1728)), row, recent, log));
    assertTrue(new MessageSearches().isMatch(SearchQuery.uid(range(1, 1729)), row, recent, log));
    assertTrue(new MessageSearches().isMatch(SearchQuery.uid(range(1729, 1800)), row, recent, log));
    assertFalse(new MessageSearches().isMatch(SearchQuery.uid(range(1730, Long.MAX_VALUE)), row, recent, log));
    assertFalse(new MessageSearches().isMatch(SearchQuery.uid(range(1730, Long.MAX_VALUE, 1, 1728)), row, recent, log));
    assertTrue(new MessageSearches().isMatch(SearchQuery.uid(range(1730, Long.MAX_VALUE, 1, 1729)), row, recent, log));
    assertFalse(new MessageSearches().isMatch(SearchQuery.uid(range(1, 1728, 1800, 1810)), row, recent, log));
    assertTrue(new MessageSearches().isMatch(SearchQuery.uid(range(1, 1, 1729, 1729)), row, recent, log));
    assertFalse(new MessageSearches().isMatch(SearchQuery.uid(range(1, 1, 1800, 1800)), row, recent, log));
}

